/bin/zsh -lc "cat > src/orchestration/chatOrchestrator.beforeSession.unit.test.ts <<'EOF'
import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('beforeSession failure', () => {
  it('passes the original session and error to onError [specs/hal-engine-config-hooks/spec.md#6]', async () => {
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const error = new Error('setup failed');
    let received: [ChatSession, Error] | undefined;
    const provider: AIProvider = {
      async *sendMessage() {},
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({baseSystemPrompt: 'test'}), undefined, {
      hooks: {
        beforeSession: async () => { throw error; },
        onError: async (s, e) => { received = [s, e]; },
      },
    });

    await expect(orchestrator.processMessage(session)).rejects.toBe(error);
    expect(received).toEqual([session, error]);
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runInBand --runTestsByPath src/orchestration/chatOrchestrator.beforeSession.unit.test.ts"
